contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We model one invocation of C.play with a caller sending `amount` wei.
    // Parameters:
    // - uint amount: the Ether value to send to c.play()
    // We assert a general rule covering both success and revert cases.
    function run(uint amount) public payable {
        // ensure this contract has enough balance to send the requested amount
        require(address(this).balance >= amount);

        // Observe pre-call values
        uint potBefore = c.pot();
        address bankAddr = address(c.bank());
        uint contractBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        // call play with provided amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        uint potAfter = c.pot();
        uint contractBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule:
        // - If the call reverted, it must be because amount != TICKET_AMOUNT (10).
        // - If the call succeeded and amount == 10, then either:
        //     * A payout happened: potAfter == 0 and contract's balance decreased by (potBefore + 10 - 1) (i.e., pot awarded minus fee), and this contract's balance did not increase by more than (potBefore + 10 - 1); or
        //     * No payout happened: potAfter == potBefore + 10 and contract's balance increased by 10 and this contract's balance decreased by 10.
        // We express this using only observable values. We avoid using the constants from C directly; instead we require equivalences based on amount.

        // Note: We cannot refer to C.TICKET_AMOUNT/FEE_AMOUNT directly, so we encode expectations relative to `amount`.
        // If reverted then amount must differ from ticket price (10). If not reverted then amount must equal 10 and one of two state transitions holds.

        // Build the assertion
        assert(
            // If reverted then amount != 10
            (reverted && amount != 10)
            // If not reverted then amount == 10 and one of the two post-state patterns holds
            || (!reverted && amount == 10 && (
                // payout happened: pot cleared
                (potAfter == 0
                    // contract balance decreased by at least potBefore + amount - 1 (since fee 1 sent to bank and rest to player)
                    && contractBalAfter + (potBefore + amount - 1) == contractBalBefore
                )
                ||
                // no payout: pot increased by amount and contract balance increased by amount
                (potAfter == potBefore + amount
                    && contractBalAfter == contractBalBefore + amount
                )
            ))
        );
    }

    // allow this test contract to receive Ether when C sends payouts
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call C.play with a chosen amount. We assert two things:
    // 1) If play() does not revert then the sent amount equals the ticket price (10).
    // 2) If play() does not revert then the pot after the call is either increased by the sent amount or is reset to 0 (payout case).
    // We observe pot via the public getter c.pot() and detect revert via try/catch.
    function run(uint amount) public payable {
        // Ensure this test contract can pay the requested amount
        require(address(this).balance >= amount);

        uint potBefore = c.pot();

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();

        // General invariant to hold for all inputs:
        // - If the call succeeded then amount == 10 (the ticket price) and the pot either grew by amount or was set to 0.
        // - If the call reverted we place no further constraint here.
        assert(
            reverted
            || (
                amount == 10
                && (
                    potAfter == potBefore + amount
                    || potAfter == 0
                )
            )
        );
    }

    // Allow receiving Ether when C pays out
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: send `amount` to c.play()
    // amount should be the ticket price to exercise the main branch
    function run(uint amount) public payable {
        // ensure this contract has enough balance to send
        require(address(this).balance >= amount);

        // observe pre-call public values
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balanceCBefore = address(c).balance;
        uint balanceThisBefore = address(this).balance;

        // perform the state-changing call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-call public values
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balanceCAfter = address(c).balance;
        uint balanceThisAfter = address(this).balance;

        // General rule:
        // - bank address is never changed by play()
        // - if the call did not revert and amount == TICKET_AMOUNT then either:
        //     * pot increased by amount (and no transfer to bank happened), OR
        //     * pot became 0 and exactly FEE_AMOUNT left contract to bank (reflected in balances)
        // - if the call reverted or amount != TICKET_AMOUNT, nothing about balances is required beyond bank immutability

        // We cannot refer to the constants TICKET_AMOUNT/FEE_AMOUNT directly, so express relation using observed balances.
        // Compute net change to contract's balance and to pot relative to sent amount.
        int netCBalanceChange = int(balanceCAfter) - int(balanceCBefore);
        int potChange = int(potAfter) - int(potBefore);

        // If call succeeded and the caller provided the exact ticket amount, then either pot increased by amount
        // (and contract balance increased by amount), or pot became zero and contract balance decreased by FEE_AMOUNT (net: -FEE_AMOUNT)
        bool ticketSent = (amount == 10);
        bool successful = (!reverted);

        bool caseA = (successful && ticketSent && potChange == int(amount) && netCBalanceChange == int(amount));
        // For caseB, potAfter == 0 and contract balance change equals -(int)1 (fee sent out) because the contract received amount then sent out pot - fee to player and fee to bank.
        bool caseB = (successful && ticketSent && potAfter == 0 && netCBalanceChange == -int(1));

        // bank address must never change
        assert(bankBefore == bankAfter && ( !successful || !ticketSent || (caseA || caseB) ));
    }

    // allow contract to receive refunds when play() transfers to msg.sender
    receive() external payable {}
}

