contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the ticket amount as input and sending that Ether
    function run(uint amount) public payable {
        // must have Ether to send
        require(address(this).balance >= amount);
        // observe before-values
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;

        // perform the call, recording whether it reverts
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        // FEE_AMOUNT is 1 in contract C; but we must express property without reading internals.
        // General rule: if call succeeded and amount equals ticket price (10), then the combined
        // on-chain assets (pot + contract balance) should change by exactly +amount minus at most 1,
        // because when a win occurs the contract pays fee of at most 1 out of the pot.

        // We cannot reference constants inside C, so express as: the decrease in (pot+balance) is at most 1,
        // and the increase is at most amount. Also if call reverted then state unchanged.

        assert(
            // If reverted: pot and balance unchanged
            (reverted && potAfter == potBefore && balAfter == balBefore)
            ||
            // If succeeded: total assets change equals amount OR amount - 1 (i.e., change is between amount-1 and amount)
            (!reverted && (
                // total change
                (int256(potAfter + balAfter) - int256(potBefore + balBefore) >= int256(amount) - 1)
                &&
                (int256(potAfter + balAfter) - int256(potBefore + balBefore) <= int256(amount))
            ))
        );
    }

    // allow receiving refunds from C during play()
    receive() external payable {}
}

